class Person {
  private String name;
  private int count;
  void setCount(int count) {
    if (count < 0) {
      throw new IllegalArgumentException();
    }
    this.count = count;
  }
  void setName(String name) {
    this.name = name.trim();
  }
  Person setLabel(String name) {
    this.name = name;
    return this;
  }
  void setDefaultName(String ignored) {
    this.name = DEFAULT_NAME;
  }
  private static final String DEFAULT_NAME = "x";
}
